with unpacked as (select id, service, log_ts, status_code, payload_json, get_json_object(payload_json, '$.duration') as duration_text, size(context) as num_context, context['version'] as version, array_contains(map_keys(context), 'region') as has_region from app_logs) select case when num_context >= 86 then 'PREMIUM' else 'STANDARD' end as num_context_tier, min(log_ts) as first_log_ts, count(*) as num_rows, round(sum(num_context) / nullif(count(case when service = 'billing' then 1 end), 0), 2) as num_context_per_billing, count_if(service = 'search') as search_events, sort_array(collect_set(service)) as service_list from unpacked group by case when num_context >= 86 then 'PREMIUM' else 'STANDARD' end;
